import re
import collections
from robot.libraries.BuiltIn import BuiltIn
from robot.api import logger
from ta_messaging.robot_utils import _is_dry_run

BUFFER_LENGTH = 50
keyword_stack = collections.deque(maxlen=BUFFER_LENGTH)
listener_cleanup_actions = []

OPTIONS_OR_NOTHING = r'(?:(\[.*?\]:|:))'
CONSTANT_HEADERS = {'expect': {'regexp': re.compile('EXPECT FLOW{}'.format(OPTIONS_OR_NOTHING)),
                               'prefix': 'EXPECT FLOW'},
                    'pass': {'regexp': re.compile('PASS FLOW{}'.format(OPTIONS_OR_NOTHING)),
                             'prefix': 'PASS FLOW'},
                    'fail': {'regexp': re.compile('FAIL FLOW{}'.format(OPTIONS_OR_NOTHING)),
                             'prefix': 'FAIL FLOW'},
                    'expect_concurrent': {'regexp': re.compile('EXPECT CONCURRENT FLOW{}'.format(OPTIONS_OR_NOTHING)),
                                          'prefix': 'EXPECT CONCURRENT FLOW'},
                    'pass_concurrent': {'regexp': re.compile('PASS CONCURRENT FLOW{}'.format(OPTIONS_OR_NOTHING)),
                                        'prefix': 'PASS CONCURRENT FLOW'},
                    'fail_concurrent': {'regexp': re.compile('FAIL CONCURRENT FLOW{}'.format(OPTIONS_OR_NOTHING)),
                                        'prefix': 'FAIL CONCURRENT FLOW'}
                    }


def get_stack():
    global keyword_stack
    return keyword_stack


def clear_stack():
    global keyword_stack
    keyword_stack = collections.deque(maxlen=BUFFER_LENGTH)


def get_last_expect_keyword(without_library_part=True):
    stack = get_stack()
    for k in stack:
        if without_library_part is True:
            return re.sub(r'.*?\.', '', k)
        else:
            return k


def register_listener_end_test_action(func):
    global listener_cleanup_actions
    if func not in listener_cleanup_actions:
        listener_cleanup_actions.append(func)


def get_listener_cleanup_actions():
    return listener_cleanup_actions


class expect_keyword_listener(object):
    ROBOT_LISTENER_API_VERSION = 2
    ROBOT_LIBRARY_SCOPE = "GLOBAL"

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self.end_test_funcs = []
        self._is_dry_run = _is_dry_run()

    def _start_keyword(self, name, attrs):
        try:
            if CONSTANT_HEADERS['expect']['prefix'] in name or \
                    CONSTANT_HEADERS['expect_concurrent']['prefix'] in name:
                keyword_variables = re.findall(r'(\$\{.*?\})', name)
                for var in list(set(keyword_variables)):
                    var_value = BuiltIn().get_variable_value(var)
                    # logger.console("{}: {}".format(var, var_value))
                    # fix for dry run error
                    if self._is_dry_run and var_value is None:
                        var_value = 'None'
                    name = name.replace(var, var_value)
                get_stack().appendleft(name)
        except Exception as e:
            logger.warn('expect_keyword_listener: exception: {}'.format(e))

    def _start_test(self, name, attr):
        if self._is_dry_run:
            return
        self.end_test_funcs = get_listener_cleanup_actions()

    def _end_test(self, name, attr):
        if self._is_dry_run:
            return
        clear_stack()
        for end_func in self.end_test_funcs:
            try:
                end_func()
            except Exception:
                pass
